import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';

export class AdminResetPasswordResponseDto {
  @ApiProperty({ description: 'The user whose password was reset' })
  userId!: number;

  // Present ONLY when the caller omitted newPassword (server autogenerated one) — shown exactly
  // once, matching the Create User wizard's own "Retrieve password" step contract: never persisted
  // in plaintext anywhere, never retrievable again after this response. Absent (not empty string)
  // when the caller supplied their own newPassword, since there is nothing new to reveal.
  @ApiPropertyOptional({ description: 'The autogenerated password — only present when newPassword was not supplied' })
  generatedPassword?: string;

  @ApiProperty()
  mustChangePassword!: boolean;

  @ApiProperty()
  sessionsRevoked!: boolean;
}
